CREATE TABLE IF NOT EXISTS backtest_replay_results (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trade_setup_id BIGINT NOT NULL, app_user_id BIGINT, broker_credentials_id BIGINT, broker_name VARCHAR(255), simulator BOOLEAN, trade_date DATE NOT NULL, source VARCHAR(255), symbol VARCHAR(255), scrip_code INTEGER, option_type VARCHAR(255), strike_price DOUBLE PRECISION, expiry VARCHAR(255), candle_interval VARCHAR(255) NOT NULL, trigger_price_policy VARCHAR(255) NOT NULL, square_off_time VARCHAR(255) NOT NULL, intraday_only BOOLEAN, status VARCHAR(255) NOT NULL, message VARCHAR(1000), backtest_entry_at TIMESTAMP, backtest_exit_at TIMESTAMP, backtest_exit_price DOUBLE PRECISION, backtest_exit_reason VARCHAR(255), backtest_pnl DOUBLE PRECISION, backtest_exit_count INTEGER, actual_entry_at TIMESTAMP, actual_exit_at TIMESTAMP, actual_exit_price DOUBLE PRECISION, actual_exit_reason VARCHAR(255), actual_pnl DOUBLE PRECISION, run_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT uk_backtest_replay_result_policy UNIQUE (trade_setup_id,candle_interval,trigger_price_policy,square_off_time));
CREATE TABLE IF NOT EXISTS backtest_replay_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, result_id BIGINT NOT NULL, trade_setup_id BIGINT NOT NULL, event_index INTEGER NOT NULL, event_at TIMESTAMP, event_type VARCHAR(255), reason VARCHAR(255), candle_interval VARCHAR(255), trigger_price_policy VARCHAR(255), square_off_time VARCHAR(255), price_source VARCHAR(255), reference_price DOUBLE PRECISION, option_price DOUBLE PRECISION, stop_loss DOUBLE PRECISION, target DOUBLE PRECISION, quantity BIGINT, lots INTEGER, pnl DOUBLE PRECISION, run_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS idx_backtest_replay_events_result ON backtest_replay_events(result_id,event_index);
